'use client';

import { AnimatePresence, motion } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import {
  pressedSolidOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { PlusIcon } from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { Badge } from '@/registry/ndeko/ui/badge';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { AddServerDialog } from './add-server-dialog';
import { AGENT_NAME } from './data';
import { ServerRow } from './server-row';
import {
  INITIAL,
  LOOP_AFTER_MS,
  RECONNECT_MS,
  reducer,
  RESTING,
  SCRIPT,
  SETTLE_MS,
  TEST_MS,
  type McpState,
  type ServerLive,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

type Reach = {
  connected: number;
  toolsOn: number;
  askFirst: number;
};

function isConnected(live: ServerLive) {
  const isSteady = live.status === 'connected';
  const isRestored = live.status === 'restored';
  return isSteady || isRestored;
}

/** Only the tools of connected servers count: the agent cannot call the others. */
function reachOf(state: McpState): Reach {
  const reach: Reach = { connected: 0, toolsOn: 0, askFirst: 0 };
  for (const server of state.servers) {
    const live = state.live[server.id];
    if (!isConnected(live)) {
      continue;
    }
    reach.connected += 1;
    for (const setting of Object.values(live.tools)) {
      if (!setting.isEnabled) {
        continue;
      }
      reach.toolsOn += 1;
      if (setting.asksFirst) {
        reach.askFirst += 1;
      }
    }
  }
  return reach;
}

function countOf(count: number, singular: string) {
  if (count === 1) {
    return `1 ${singular}`;
  }
  return `${count} ${singular}s`;
}

function reachLineOf(reach: Reach, total: number) {
  const servers = countOf(total, 'server');
  const tools = countOf(reach.toolsOn, 'tool');
  return `${reach.connected} of ${servers} connected, ${tools} on, ${reach.askFirst} ask first`;
}

type ReachFigureProps = {
  label: string;
  value: number;
  suffix?: string;
};

function ReachFigure({ label, value, suffix }: ReachFigureProps) {
  return (
    <div className='flex min-w-0 flex-col gap-0.5'>
      <dt className='text-muted-foreground text-xs'>{label}</dt>
      <dd className='flex items-baseline gap-1.5'>
        <MotionNumber
          value={value}
          className='text-2xl leading-8 font-semibold'
        />
        {suffix && (
          <span className='text-muted-foreground text-xs tabular-nums'>
            {suffix}
          </span>
        )}
      </dd>
    </div>
  );
}

export default function AgentOps04() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule } = useTimeouts();
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const reach = reachOf(state);
  const serverCount = state.servers.length;
  const isEmpty = serverCount === 0;
  const reachLine = reachLineOf(reach, serverCount);
  const message = spokenUnless(isAutoplaying, reachLine);
  const canReplay = isFinished && !isAutoplaying;

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  function reconnect(id: string) {
    act({ type: 'reconnect', id });
    schedule(() => act({ type: 'reconnected', id }), RECONNECT_MS);
    schedule(() => act({ type: 'settled', id }), RECONNECT_MS + SETTLE_MS);
  }

  function test() {
    act({ type: 'test' });
    schedule(() => act({ type: 'tested' }), TEST_MS);
  }

  function openDialog() {
    act({ type: 'dialogOpened' });
    focusLater('[data-dialog-first]');
  }

  function closeDialog() {
    act({ type: 'dialogClosed' });
    focusLater('[data-add-server]');
  }

  function addServer() {
    act({ type: 'added' });
    focusLater('[data-add-server]');
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container relative h-dvh min-h-[40rem] w-full overflow-hidden'
      >
        <div inert={state.dialog.isOpen} className='h-full overflow-y-auto'>
          <div className='mx-auto flex max-w-3xl flex-col gap-5 p-4 @3xl:p-8'>
            <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
              <BrandTile brand='mcp' size='lg' />
              <div className='flex min-w-40 flex-1 flex-col leading-tight'>
                <h1 className='text-lg font-semibold text-balance'>
                  MCP servers
                </h1>
                <p className='text-muted-foreground text-xs'>
                  What the {AGENT_NAME} can reach
                </p>
              </div>
              <ReplayButton
                isShown={canReplay}
                onReplay={restart}
                label='Replay the setup'
              />
              <Button
                type='button'
                data-add-server
                onClick={openDialog}
                className={pressedSolidOf(pressed === 'add')}
              >
                <PlusIcon />
                Add server
              </Button>
            </header>

            <dl className='grid grid-cols-3 gap-3'>
              <ReachFigure
                label='Connected'
                value={reach.connected}
                suffix={`of ${serverCount}`}
              />
              <ReachFigure label='Tools on' value={reach.toolsOn} />
              <ReachFigure label='Ask first' value={reach.askFirst} />
            </dl>

            <section
              aria-label='Servers'
              className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex flex-col rounded-xl p-1 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
            >
              <ul className='flex flex-col'>
                <AnimatePresence initial={false}>
                  {state.servers.map((server) => (
                    <motion.li
                      key={server.id}
                      className='overflow-hidden'
                      {...rowPresence}
                    >
                      <ServerRow
                        server={server}
                        live={state.live[server.id]}
                        isOpen={state.openId === server.id}
                        isRemoving={state.removingId === server.id}
                        pressed={pressed}
                        onAction={act}
                        onReconnect={reconnect}
                      />
                    </motion.li>
                  ))}
                </AnimatePresence>
              </ul>
              {isEmpty && (
                <div className='flex flex-col items-start gap-3 p-3 transition-opacity duration-300 starting:opacity-0'>
                  <p className='text-muted-foreground text-[13px]'>
                    No server is connected, so the agent has no tools. Add one
                    to give it something to work with.
                  </p>
                  <Button
                    type='button'
                    variant='outline'
                    size='sm'
                    onClick={openDialog}
                  >
                    <PlusIcon />
                    Add server
                  </Button>
                </div>
              )}
            </section>

            <Badge variant='secondary' className='self-start'>
              Illustrative tool lists
            </Badge>
          </div>
        </div>

        <AddServerDialog
          dialog={state.dialog}
          pressed={pressed}
          onAction={act}
          onTest={test}
          onAdd={addServer}
          onClose={closeDialog}
        />
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { useId } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll } from '@/components/core/word-roll';
import { ChevronDownIcon, Trash2Icon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { Chip } from '@/registry/ndeko/ui/chip';
import { LetterTile } from '@/registry/ndeko/ui/letter-tile';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { StatusOrb, type StatusOrbTone } from '@/registry/ndeko/ui/status-orb';
import { Switch } from '@/registry/ndeko/ui/switch';

import { TRANSPORT_WORD, type Access, type Server, type Tool } from './data';
import {
  enabledCountOf,
  type ConnectionStatus,
  type McpAction,
  type ServerLive,
  type ToolSetting,
} from './session';

const STATUS_WORD: Record<ConnectionStatus, string> = {
  connected: 'Connected',
  expired: 'Token expired',
  reconnecting: 'Reconnecting',
  restored: 'Connected',
};

const STATUS_WORDS = ['Connected', 'Token expired', 'Reconnecting'];

const ORB_TONE: Record<ConnectionStatus, StatusOrbTone> = {
  connected: 'success',
  expired: 'error',
  reconnecting: 'loading',
  restored: 'success',
};

const WORD_TONE: Record<ConnectionStatus, string> = {
  connected: 'text-muted-foreground',
  expired: 'text-destructive-ink',
  reconnecting: 'text-muted-foreground',
  restored: 'text-muted-foreground',
};

const REASON_TONE: Record<ConnectionStatus, string> = {
  connected: 'text-foreground',
  expired: 'text-destructive-ink',
  reconnecting: 'text-foreground',
  restored: 'text-foreground',
};

const RECONNECT_STATE: Record<ConnectionStatus, MorphState> = {
  connected: 'done',
  expired: 'idle',
  reconnecting: 'busy',
  restored: 'done',
};

const RECONNECT_LABELS: Record<MorphState, string> = {
  idle: 'Reconnect',
  busy: 'Reconnecting',
  done: 'Connected',
};

const REASON_LINE: Record<ConnectionStatus, string> = {
  connected: 'Signed in. The tools are back',
  expired: 'The agent cannot use these tools until you sign in again',
  reconnecting: 'Asking for a new token',
  restored: 'Signed in. The tools are back',
};

const ACCESS_WORD: Record<Access, string> = { read: 'Read', write: 'Write' };

const ACCESS_COLOR: Record<Access, string> = {
  read: 'var(--muted-foreground)',
  write: 'var(--warning)',
};

function toolsWordOf(count: number) {
  if (count === 1) {
    return 'tool on';
  }
  return 'tools on';
}

function lostToolsOf(count: number) {
  if (count === 1) {
    return 'its tool';
  }
  return `its ${count} tools`;
}

function chevronTurnOf(isOpen: boolean) {
  if (isOpen) {
    return 'rotate-180';
  }
  return 'rotate-0';
}

function pressedQuietOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-foreground/[0.07] text-foreground';
  }
  return undefined;
}

function toggleLabelOf(server: Server, isOpen: boolean) {
  if (isOpen) {
    return `Hide the tools of ${server.name}`;
  }
  return `Show the tools of ${server.name}`;
}

function removeVariantOf(isRemoving: boolean) {
  if (isRemoving) {
    return 'destructive';
  }
  return 'ghost';
}

function removeLabelOf(server: Server, isRemoving: boolean) {
  if (isRemoving) {
    return `Remove ${server.name}`;
  }
  return 'Remove server';
}

function ServerTile({ server }: { server: Server }) {
  if (server.brand) {
    return <BrandTile brand={server.brand} size='lg' />;
  }
  return <LetterTile initial={server.initial} size='lg' />;
}

type ToolRowProps = {
  serverId: string;
  tool: Tool;
  setting: ToolSetting;
  onAction: (action: McpAction) => void;
};

function ToolRow({ serverId, tool, setting, onAction }: ToolRowProps) {
  function setEnabled(isEnabled: boolean) {
    onAction({ type: 'toolEnabled', id: serverId, tool: tool.name, isEnabled });
  }

  function setAsksFirst(asksFirst: boolean) {
    onAction({ type: 'toolAsks', id: serverId, tool: tool.name, asksFirst });
  }

  return (
    <li className='bg-foreground/[0.03] dark:bg-foreground/[0.05] flex flex-col gap-2 rounded-lg px-2.5 py-2 @xl:flex-row @xl:items-center @xl:gap-4'>
      <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
        <p className='flex flex-wrap items-center gap-2'>
          <code className='font-mono text-xs'>{tool.name}</code>
          <Chip color={ACCESS_COLOR[tool.access]}>
            {ACCESS_WORD[tool.access]}
          </Chip>
        </p>
        <p className='text-muted-foreground text-xs'>{tool.summary}</p>
      </div>
      <div className='flex shrink-0 items-center gap-4'>
        <label className='flex cursor-pointer items-center gap-2 text-xs'>
          <Switch
            checked={setting.isEnabled}
            onCheckedChange={setEnabled}
            aria-label={`Let the agent use ${tool.name}`}
          />
          Enabled
        </label>
        <label
          className={cn(
            'flex cursor-pointer items-center gap-2 text-xs transition-opacity duration-200',
            !setting.isEnabled && 'cursor-not-allowed opacity-50'
          )}
        >
          <Switch
            checked={setting.asksFirst}
            disabled={!setting.isEnabled}
            onCheckedChange={setAsksFirst}
            aria-label={`Ask first before ${tool.name}`}
          />
          Ask first
        </label>
      </div>
    </li>
  );
}

export type ServerRowProps = {
  server: Server;
  live: ServerLive;
  isOpen: boolean;
  isRemoving: boolean;
  pressed: string | null;
  onAction: (action: McpAction) => void;
  onReconnect: (id: string) => void;
};

export function ServerRow({
  server,
  live,
  isOpen,
  isRemoving,
  pressed,
  onAction,
  onReconnect,
}: ServerRowProps) {
  const panelId = useId();
  const enabledCount = enabledCountOf(live);
  const toolCount = server.tools.length;
  const needsAttention = live.status !== 'connected';
  const removeLabel = removeLabelOf(server, isRemoving);

  function removeStep() {
    if (isRemoving) {
      onAction({ type: 'removed', id: server.id });
      return;
    }
    onAction({ type: 'removeAsked', id: server.id });
  }

  return (
    <div className='flex flex-col px-2 py-2.5'>
      <div className='flex items-center gap-3'>
        <ServerTile server={server} />
        <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
          <p className='flex flex-wrap items-center gap-x-2 gap-y-0.5'>
            <span className='text-[13px] leading-5 font-medium'>
              {server.name}
            </span>
            <Badge variant='secondary'>
              {TRANSPORT_WORD[server.transport]}
            </Badge>
          </p>
          <p className='text-muted-foreground flex min-w-0 items-center gap-1 text-xs'>
            <MotionNumber value={enabledCount} />
            <span className='shrink-0'>
              of {toolCount} {toolsWordOf(toolCount)}
            </span>
            {server.address && (
              <code className='min-w-0 truncate ps-1 font-mono'>
                {server.address}
              </code>
            )}
          </p>
        </div>
        <div className='flex shrink-0 items-center gap-2'>
          <span
            className={cn(
              'hidden text-xs transition-colors duration-200 @md:block',
              WORD_TONE[live.status]
            )}
          >
            <WordRoll text={STATUS_WORD[live.status]} labels={STATUS_WORDS} />
          </span>
          <StatusOrb tone={ORB_TONE[live.status]} size='sm' />
          <span className='sr-only @md:hidden'>{STATUS_WORD[live.status]}</span>
        </div>
        <Button
          type='button'
          variant='ghost'
          size='icon-sm'
          aria-expanded={isOpen}
          aria-controls={panelId}
          aria-label={toggleLabelOf(server, isOpen)}
          onClick={() => onAction({ type: 'toggled', id: server.id })}
          className={cn(
            'text-muted-foreground',
            pressedQuietOf(pressed === `toggle-${server.id}`)
          )}
        >
          <ChevronDownIcon
            className={cn(
              'transition-transform duration-200 ease-(--ease-out-strong)',
              chevronTurnOf(isOpen)
            )}
          />
        </Button>
      </div>

      <Fold open={needsAttention} className='ps-10'>
        <div className='flex flex-wrap items-center gap-x-3 gap-y-2 pt-2'>
          <p className='min-w-0 flex-1 text-xs'>
            <span
              className={cn(
                'font-medium transition-colors duration-200 @md:hidden',
                REASON_TONE[live.status]
              )}
            >
              {STATUS_WORD[live.status]}.{' '}
            </span>
            <span className='text-muted-foreground'>
              <Swap swapKey={live.status}>{REASON_LINE[live.status]}</Swap>
            </span>
          </p>
          <MorphButton
            type='button'
            size='sm'
            variant='outline'
            state={RECONNECT_STATE[live.status]}
            labels={RECONNECT_LABELS}
            onClick={() => onReconnect(server.id)}
            className={pressedQuietOf(pressed === `reconnect-${server.id}`)}
          />
        </div>
      </Fold>

      <Fold open={isOpen} id={panelId} className='ps-10'>
        <ul
          aria-label={`Tools of ${server.name}`}
          className='flex flex-col gap-1 pt-2'
        >
          {server.tools.map((tool) => (
            <ToolRow
              key={tool.name}
              serverId={server.id}
              tool={tool}
              setting={live.tools[tool.name]}
              onAction={onAction}
            />
          ))}
        </ul>
        <div className='flex flex-wrap items-center gap-x-3 gap-y-2 pt-2'>
          <Button
            type='button'
            size='sm'
            variant={removeVariantOf(isRemoving)}
            onClick={removeStep}
            className={cn(!isRemoving && 'text-destructive-ink')}
          >
            <Trash2Icon />
            <Swap swapKey={removeLabel}>{removeLabel}</Swap>
          </Button>
          {isRemoving && (
            <>
              <Button
                type='button'
                size='sm'
                variant='ghost'
                onClick={() => onAction({ type: 'removeCancelled' })}
                className='transition-opacity duration-200 starting:opacity-0'
              >
                Keep it
              </Button>
              <p className='text-muted-foreground text-xs transition-opacity duration-200 starting:opacity-0'>
                The agent loses {lostToolsOf(toolCount)}
              </p>
            </>
          )}
        </div>
      </Fold>
    </div>
  );
}

'use client';

import { useId } from 'react';

import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { CheckIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { Input } from '@/registry/ndeko/ui/input';
import { Label } from '@/registry/ndeko/ui/label';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';
import { Spinner } from '@/registry/ndeko/ui/spinner';

import { DEMO_NAME, FOUND_TOOLS, type Transport } from './data';
import type { DialogState, McpAction, TestStatus } from './session';

const TRANSPORTS: Segment<Transport>[] = [
  { value: 'remote', label: 'Remote' },
  { value: 'local', label: 'Local' },
];

const ADDRESS_LABEL: Record<Transport, string> = {
  remote: 'Server URL',
  local: 'Command',
};

const ADDRESS_HINT: Record<Transport, string> = {
  remote: 'https://mcp.example.dev/mcp',
  local: 'node ./mcp/server.js',
};

const TEST_STATE: Record<TestStatus, MorphState> = {
  idle: 'idle',
  testing: 'busy',
  connected: 'done',
  failed: 'idle',
};

const TEST_LABELS: Record<MorphState, string> = {
  idle: 'Test connection',
  busy: 'Testing',
  done: 'Connected',
};

function layerOf(isOpen: boolean) {
  if (isOpen) {
    return undefined;
  }
  return 'pointer-events-none';
}

function backdropOf(isOpen: boolean) {
  if (isOpen) {
    return 'opacity-100';
  }
  return 'opacity-0';
}

function panelOf(isOpen: boolean) {
  if (isOpen) {
    return 'scale-100 opacity-100';
  }
  return 'scale-95 opacity-0 duration-150';
}

function pressedQuietOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-foreground/[0.07]';
  }
  return undefined;
}

function toolsFoundOf(count: number) {
  if (count === 1) {
    return '1 tool found';
  }
  return `${count} tools found`;
}

function TestResult({ dialog }: { dialog: DialogState }) {
  if (dialog.test === 'testing') {
    return (
      <p className='text-muted-foreground flex items-center gap-2 text-[13px]'>
        <Spinner label='Testing the connection' />
        Testing the connection
      </p>
    );
  }
  if (dialog.test === 'failed') {
    return (
      <div className='bg-destructive/10 flex items-start gap-2.5 rounded-lg p-3'>
        <XIcon className='text-destructive-ink mt-0.5 size-4 shrink-0' />
        <div className='flex min-w-0 flex-col gap-0.5'>
          <p className='text-destructive-ink text-[13px] font-medium'>Failed</p>
          <p className='text-[13px] leading-relaxed'>{dialog.failure}</p>
        </div>
      </div>
    );
  }
  if (dialog.test === 'connected') {
    return (
      <div className='bg-success/10 flex items-start gap-2.5 rounded-lg p-3'>
        <CheckIcon className='text-success-foreground mt-0.5 size-4 shrink-0' />
        <div className='flex min-w-0 flex-col gap-2'>
          <p className='text-success-foreground text-[13px] font-medium'>
            Connected, {toolsFoundOf(FOUND_TOOLS.length)}
          </p>
          <ul className='flex flex-wrap gap-1'>
            {FOUND_TOOLS.map((tool) => (
              <li
                key={tool.name}
                className='bg-card/70 dark:bg-foreground/[0.06] rounded-sm px-1.5 py-0.5 font-mono text-[11px]'
              >
                {tool.name}
              </li>
            ))}
          </ul>
        </div>
      </div>
    );
  }
  return null;
}

export type AddServerDialogProps = {
  dialog: DialogState;
  pressed: string | null;
  onAction: (action: McpAction) => void;
  onTest: () => void;
  onAdd: () => void;
  onClose: () => void;
};

/** Drawn inside the block, so the demonstration never opens a layer over the rest of the page. */
export function AddServerDialog({
  dialog,
  pressed,
  onAction,
  onTest,
  onAdd,
  onClose,
}: AddServerDialogProps) {
  const titleId = useId();
  const nameId = useId();
  const addressId = useId();
  const isOpen = dialog.isOpen;
  const isTesting = dialog.test === 'testing';
  const canAdd = dialog.test === 'connected';
  const addressLabel = ADDRESS_LABEL[dialog.transport];

  function closeOnEscape(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'Escape') {
      onClose();
    }
  }

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (canAdd) {
      onAdd();
    }
  }

  return (
    <div
      inert={!isOpen}
      onKeyDown={closeOnEscape}
      className={cn('absolute inset-0 z-20', layerOf(isOpen))}
    >
